<script setup>
import { computed } from 'vue';
const props = defineProps({ type: { default: 'line' }, values: { default: () => [24,36,48,62,74,88,102] }, total: { default: '24' }, caption: { default: '总任务' }, labels: { default: () => ['已完成','进行中','待处理','已延期'] }, colors: { default: () => ['#1986ff','#16c99b','#ff8b2b','#9153ff'] } });
const points = computed(() => props.values.map((v,i) => `${28+i*310/(props.values.length-1)},${145-v*1.1}`).join(' '));
const stops = computed(() => { let p=0; const total=props.values.reduce((a,b)=>a+b,0); return props.values.map((v,i)=>{const start=p;p+=v/total*100;return `${props.colors[i%props.colors.length]} ${start}% ${p}%`}).join(',') });
</script>
<template>
 <div v-if="type==='donut'" class="donut-layout"><div class="donut" :style="{background:`conic-gradient(${stops})`}"><div><strong>{{ total }}</strong><small>{{ caption }}</small></div></div><div class="legend"><div v-for="(label,i) in labels" :key="label"><i :style="{background:colors[i%colors.length]}"/><span>{{ label }}</span><b>{{ values[i] }}</b><small>{{ Math.round(values[i]/values.reduce((a,b)=>a+b,0)*100) }}%</small></div></div></div>
 <svg v-else-if="type==='line'" class="line-chart" viewBox="0 0 355 180" role="img" aria-label="任务趋势折线图"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#39a7ff" stop-opacity=".28"/><stop offset="1" stop-color="#39a7ff" stop-opacity=".01"/></linearGradient></defs><g stroke="#e8f0f7" stroke-width=".7"><path v-for="y in [25,55,85,115,145]" :key="y" :d="`M28 ${y} H342`"/><path v-for="x in [28,80,132,184,236,288,340]" :key="x" :d="`M${x} 20 V145`"/></g><g font-size="9" fill="#8596af"><text v-for="(v,i) in ['120','90','60','30','0']" :key="v" x="4" :y="29+i*30">{{ v }}</text><text v-for="(v,i) in ['10/14','10/15','10/16','10/17','10/18','10/19','10/20']" :key="v" :x="17+i*51" y="168">{{ v }}</text></g><polygon :points="`28,145 ${points} 338,145`" fill="url(#area)"/><polyline :points="points" fill="none" stroke="#1986ff" stroke-width="2"/><polyline :points="values.map((v,i)=>`${28+i*310/(values.length-1)},${150-v*.83}`).join(' ')" fill="none" stroke="#16c99b" stroke-width="2"/><circle v-for="(v,i) in values" :key="i" :cx="28+i*310/(values.length-1)" :cy="145-v*1.1" r="3" fill="#1986ff" stroke="white"/><text x="336" :y="140-values.at(-1)*1.1" font-size="10" fill="#1986ff">{{values.at(-1)}}</text></svg>
 <div v-else class="bar-chart"><div v-for="(v,i) in values" :key="i" class="bar-col"><strong>{{v}}</strong><div :style="{height:`${v*25}px`,background:colors[i%colors.length]}"/><small>{{ labels[i] }}</small></div></div>
</template>
